from ...ute_common_config.config import Config
from ...ute_common_validator.validator import IsIpAddress, IsOneOf, IsNumber, Assert


class UTE_DCM(Config):
    """This class describes the configuration parameters for the UTE DCM testline variant."""

    TDD_CPRI_TYPE = [1, 2]

    def __init__(self,
                 enb_type='lrc',
                 enb_pdu_ip='0.0.0.0',
                 enb_pdu_outlet=0,
                 iphy_pdu_ip='0.0.0.0',
                 iphy_pdu_outlet=0,
                 ute_control_pc_host='0.0.0.0',
                 enb_control_pc_host='0.0.0.0',
                 epc_host='0.0.0.0',
                 l3sim_host='0.0.0.0',
                 enb_pdu_type='apc',
                 iphy_pdu_type='apc',
                 enb_control_pc_user='ute',
                 enb_control_pc_password='ute',
                 enb_control_pc_mmt_dct0='1',
                 enb_control_pc_mmt_dct1='4',
                 dct_tshark_monitor1='3',
                 dct_tshark_monitor2='4',
                 dct_interface_list=[],
                 secgw_host='0.0.0.0',
                 dct_host='0.0.0.0',
                 dct_pc_tshark_dct0='',
                 dct_pc_tshark_dct1='',
                 dct_host_3g='0.0.0.0',
                 rnc_3g_host='0.0.0.0',
                 tm500_3g_host='0.0.0.0',
                 tm500_ver='HSUPA - E4.0.4',
                 tm500_app_path='',
                 tm500_lte_host='0.0.0.0',
                 tm500_lte_version='',
                 enb_dct_0=1,
                 enb_dct_1=0,
                 enb_lbi=0,
                 enb_lca=0,
                 enb_dct_list=[1, 0],
                 enb_lcp_list=[0],
                 enb_lsp_list=[0],
                 enb_fan_list=[0, 1, 2, 3],
                 enb_lbr_list=[0],
                 enb_lps_list=[],
                 enb_lni_list=[0],
                 enb_cpri_links=None,
                 has_mmt_tool=True,
                 iphy_type=None,
                 cpri_links_type=None,
                 cpri_links_to_iphy=None,
                 iphy_physical_id_list=None,
                 enb_3g_cpri_links=None,
                 enb_3g_lsp_list=None,
                 dct_3gtshark_monitor1='2',
                 gnb_pdu_ip='0.0.0.0',
                 gnb_pdu_outlet=0,
                 gnb_pdu_type='apc',
                 gnb_control_pc_host='0.0.0.0',
                 gnb_control_pc_ne3s_interface='eth1',
                 lni0_hwy_link_speed='1Gbps',
                 lni0_hwy_port=None,
                 lni1_hwy_link_speed='1Gbps',
                 lni1_hwy_port=None,
                 enb_radio_type_list=None,
                 gnb_id_list=None,
                 gnb_card_slot=None,
                 gnb_fh_connect=None,
                 gnb_fh_bitrate=None,
                 oam_airframe_kvm_host='0.0.0.0',
                 oam_airframe_l3sim_host='0.0.0.0',
                 oam_airframe_mmt_host='0.0.0.0',
                 oam_airframe_mmt_dct0='1',):

        """
        :param string  enb_type:              eNB type . Supported values: macro, urec, lrc.
        :param string  enb_pdu_ip:            eNB PDU IP address.
        :param string  enb_pdu_type:          eNB PDU type (usb,apc,moxa)
        :param integer enb_pdu_outlet:        eNB PDU outlet number eNB is connected to.
        :param string  iphy_pdu_ip:           iPHY PDU IP address.
        :param string  iphy_pdu_type:         iPHY PDU type (usb,apc)
        :param integer iphy_pdu_outlet:       iPHY PDU outlet number I-PHY is connected to.
        :param string  ute_control_pc_host:   UTE Control PC IP address.
        :param string  enb_control_pc_host:   eNB Control PC IP address.
        :param string  enb_control_pc_user:   eNB Control PC user name.
        :param string  enb_control_pc_password:   eNB Control PC password.
        :param string  enb_control_pc_mmt_dct0:   the index for dct0(129.192) when collect mmt thark log
        :param string  enb_control_pc_mmt_dct0:   the index for dct1(130.192) when collect mmt thark log
        :param string  dct_tshark_monitor1:   the index for trans team to collect tshark log from enb HWY-MON 1
        :param string  dct_tshark_monitor2:   the index for trans team to collect tshark log from enb HWY-MON 2
        :param string  epc_host:              ePCsim IP address.
        :param string  l3sim_host:            L3sim  IP address.
        :param string  secgw_host:            security gateway IP address.
        :param string  dct_host:              dct server IP address, if equal '0.0.0.0', use enb_control_pc_host
        :param string  dct_pc_tshark_dct0:    the interface for collecting tshark on 129.194
        :param string  dct_pc_tshark_dct1:    the interface for collecting tshark on 130.194
        :param integer enb_dct_0:             eNB DCT port 0 usage.
        :param integer enb_dct_1:             eNB DCT port 0 usage.
        :param integer enb_lbi:               eNB board LBI usage.
        :param integer enb_lca:               eNB board LCA usage.
        :param list enb_cpri_links:           eNB cpri links id list.
        :param list iphy_type:                iphy or fsih.
        :param list cpri_links_type:          0:2.4G, 1:4.9G, 2:9.8G
        :param list cpri_links_to_iphy:       valid links: 1 - 4
        :param list iphy_physical_id_list:    physical id match to enb_cpri_links
        :param list enb_3g_cpri_links:        cpri link id for 3G
        :param list enb_3g_lsp_list:          lsp list for 3G
        :param string dct_3gtshark_monitor1:  network port for 3g tshark log.
        :param string gnb_pdu_ip:             gNB PDU IP address.
        :param string gnb_pdu_type:           gNB PDU type (usb,apc,moxa)
        :param integer gnb_pdu_outlet:        gNB PDU outlet number eNB is connected to.
        :param string gnb_control_pc_host:    gNB Control PC IP address.
        :param string gnb_control_pc_ne3s_interface:  network port for ne3s log.
        :param string lni0_hwy_link_speed:    HWY link speed adaption on LNI0, will a a list if needed.
        :param list lni0_hwy_port:          HWY ports used in lni0_hwy_link_speed.
        :param string lni1_hwy_link_speed:    HWY link speed adaption on LNI1, will a a list if needed.
        :param list lni1_hwy_port:          HWY port used in lni1_hwy_link_speed.
        :param list enb_radio_type_list:      radio type linked to enb cpri.
        :param list gnb_id_list:              Gnb ids connected to enb.
        :param list gnb_card_slot:            card slots inserted on gNBs, e.g. [[1,2], [1,3,4], [1,2,3,4,5,6,7,8]].
        :param list gnb_fh_connect:           front haul links on gNB ABILs, e.g. [[1,2],   [3,4],   [5,6,7,8]].
        :param list gnb_fh_bitrate:           bit rate mapping to gnb_fh_connect, e.g. [[10,10], [10,10], [10,10,10]].
        :param string oam_airframe_kvm_host:  ip of cOAM AF KVM host
        :param string oam_airframe_l3sim_host: ip of cOAM AF l3sim.
        :param string oam_airframe_mmt_host:   ip of cOAM MMT PC.
        :param string oam_airframe_mmt_dct0:  eth port to collect MMT tshark log.
        """
        super(UTE_DCM, self).__init__()

        ip_validator = IsIpAddress()
        number_validator = IsNumber()
        enb_type_validator = IsOneOf("macro", "urec", "lrc")
        link_speed_validator = IsOneOf("1Gbps", "10Gbps")
        pdu_type_validator = IsOneOf("usb", "apc", "moxa", "facom", 'aten', 'epc')
        tm500_type_validator = IsOneOf("HSUPA - E4.0.4", "LTE - LME5.0.1.REV55", "R10 HSPA SUE - WSC1.1.4 REV82",
                                       "R9 HSPA SUE - WSB4.2.6", "5G NR - NLA 4.4.0")

        iphy_pdu_ip = self.list_validator(iphy_pdu_ip, str, ip_validator, 'iphy_pdu_ip')

        iphy_pdu_outlet = self.list_validator(iphy_pdu_outlet, int, number_validator, 'iphy_pdu_outlet')

        rnc_3g_host = self.list_validator(rnc_3g_host, str, ip_validator, 'rnc_3g_host')

        tm500_3g_host = self.list_validator(tm500_3g_host, str, ip_validator, 'tm500_3g_host')

        self._set_attr("enb_type", enb_type, enb_type_validator)
        self._set_attr("enb_pdu_ip", enb_pdu_ip, ip_validator)
        self._set_attr("enb_pdu_type", enb_pdu_type, pdu_type_validator)
        self._set_attr("enb_pdu_outlet", enb_pdu_outlet, number_validator)
        self._set_attr("iphy_pdu_ip", iphy_pdu_ip)
        self._set_attr("iphy_pdu_type", iphy_pdu_type, pdu_type_validator)
        self._set_attr("iphy_pdu_outlet", iphy_pdu_outlet)
        self._set_attr("ute_control_pc_host", ute_control_pc_host, ip_validator)
        self._set_attr("enb_control_pc_host", enb_control_pc_host, ip_validator)
        self._set_attr("enb_control_pc_user", enb_control_pc_user)
        self._set_attr("enb_control_pc_password", enb_control_pc_password)

        self._set_attr("enb_control_pc_mmt_dct0", enb_control_pc_mmt_dct0)
        self._set_attr("enb_control_pc_mmt_dct1", enb_control_pc_mmt_dct1)
        self._set_attr("dct_tshark_monitor1", dct_tshark_monitor1)
        self._set_attr("dct_tshark_monitor2", dct_tshark_monitor2)
        self._set_attr("dct_interface_list", dct_interface_list)

        self._set_attr("epc_host", epc_host, ip_validator)
        self._set_attr("l3sim_host", l3sim_host, ip_validator)
        self._set_attr("secgw_host", secgw_host, ip_validator)
        self._set_attr("dct_host", dct_host, ip_validator)
        self._set_attr("dct_pc_tshark_dct0", dct_pc_tshark_dct0)
        self._set_attr("dct_pc_tshark_dct1", dct_pc_tshark_dct1)
        self._set_attr("dct_host_3g", dct_host_3g, ip_validator)
        self._set_attr("rnc_3g_host", rnc_3g_host)
        self._set_attr("tm500_3g_host", tm500_3g_host)
        self._set_attr("tm500_ver", tm500_ver, tm500_type_validator)
        self._set_attr("tm500_lte_host", tm500_lte_host)
        self._set_attr("tm500_lte_version", tm500_lte_version)
        self._set_attr("enb_dct_0", enb_dct_0, number_validator)
        self._set_attr("enb_dct_1", enb_dct_1, number_validator)

        self._set_attr("enb_lbi", enb_lbi, number_validator)
        self._set_attr("enb_lca", enb_lca, number_validator)

        self._set_attr("enb_dct_list", enb_dct_list)
        self._set_attr("enb_lcp_list", enb_lcp_list)
        self._set_attr("enb_lsp_list", enb_lsp_list)
        self._set_attr("enb_fan_list", enb_fan_list)
        self._set_attr("enb_lbr_list", enb_lbr_list)
        self._set_attr("enb_lps_list", enb_lps_list)
        self._set_attr("enb_lni_list", enb_lni_list)
        self._set_attr("has_mmt_tool", has_mmt_tool)
        self._set_attr("tm500_app_path", tm500_app_path)

        self._set_cpri_link_paras(enb_cpri_links,
                                  iphy_pdu_ip,
                                  iphy_type,
                                  cpri_links_type,
                                  cpri_links_to_iphy,
                                  iphy_physical_id_list)
        if not enb_3g_cpri_links:
            enb_3g_cpri_links = []
        if not enb_3g_lsp_list:
            enb_3g_lsp_list = []
        self._set_attr("enb_3g_cpri_links", enb_3g_cpri_links)
        self._set_attr("enb_3g_lsp_list", enb_3g_lsp_list)
        self._set_attr("dct_3gtshark_monitor1", dct_3gtshark_monitor1)

        gnb_pdu_ip = self.list_validator(gnb_pdu_ip, str, ip_validator, 'gnb_pdu_ip')
        gnb_pdu_outlet = self.list_validator(gnb_pdu_outlet, int, number_validator, 'gnb_pdu_outlet')
        gnb_control_pc_host = self.list_validator(gnb_control_pc_host, str, ip_validator, 'gnb_control_pc_host')
        lni0_hwy_link_speed = self.list_validator(lni0_hwy_link_speed, str, link_speed_validator, 'lni0_hwy_link_speed')
        lni1_hwy_link_speed = self.list_validator(lni1_hwy_link_speed, str, link_speed_validator, 'lni1_hwy_link_speed')
        self._set_attr("gnb_pdu_ip", gnb_pdu_ip)
        self._set_attr("gnb_pdu_type", gnb_pdu_type, pdu_type_validator)
        self._set_attr("gnb_pdu_outlet", gnb_pdu_outlet)
        self._set_attr("gnb_control_pc_host", gnb_control_pc_host)
        self._set_attr("gnb_control_pc_ne3s_interface", gnb_control_pc_ne3s_interface)
        self._set_attr("lni0_hwy_link_speed", lni0_hwy_link_speed)
        self._set_attr("lni1_hwy_link_speed", lni1_hwy_link_speed)

        if lni0_hwy_port is None:
            lni0_hwy_port = [0]
        if lni1_hwy_port is None:
            lni1_hwy_port = [1]

        lni0_hwy_port = self.list_validator(lni0_hwy_port, int, number_validator, 'lni0_hwy_port')
        lni1_hwy_port = self.list_validator(lni1_hwy_port, int, number_validator, 'lni1_hwy_port')

        self._set_attr("lni0_hwy_port", lni0_hwy_port)
        self._set_attr("lni1_hwy_port", lni1_hwy_port)
        self._set_attr("enb_radio_type_list", enb_radio_type_list)
        self._set_attr("gnb_id_list", gnb_id_list)
        self._set_attr("gnb_card_slot", gnb_card_slot)
        self._set_attr("gnb_fh_connect", gnb_fh_connect)
        self._set_attr("gnb_fh_bitrate", gnb_fh_bitrate)

        self._classify_radios(enb_radio_type_list)

        if oam_airframe_l3sim_host == '0.0.0.0':
            oam_airframe_l3sim_host = ute_control_pc_host

        self._set_attr('oam_airframe_kvm_host', oam_airframe_kvm_host)
        self._set_attr('oam_airframe_l3sim_host', oam_airframe_l3sim_host)
        self._set_attr('oam_airframe_mmt_host', oam_airframe_mmt_host)
        self._set_attr('oam_airframe_mmt_dct0', oam_airframe_mmt_dct0)

    def _set_cpri_link_paras(self,  # noqa: C901
                             enb_cpri_links,
                             iphy_pdu_ip,
                             iphy_type,
                             cpri_links_type,
                             cpri_links_to_iphy,
                             iphy_physical_id_list):
        enb_cpri_links_validator = Assert(lambda eclv_list: all((int(eclv_it) in range(1, 49) for eclv_it in
                                                                 eclv_list)), 'enb_cpri_link must be 1-48')

        iphy_type_validator = Assert(lambda iphy_type_list: all((iphy_type_it in ['iphy', 'fsih'] for iphy_type_it in
                                                                 iphy_type_list)), 'iphy_type must be iphy or fsih')
        cpri_links_type_validator = Assert(lambda clt_list: all((clt_it in [0, 1, 2] for clt_it in
                                                                 clt_list)), 'cpri_links_type must be 0 1 2')

        cpri_links_to_iphy_validator = Assert(lambda clti_list: all((clti_it in [1, 2, 3, 4] for clti_it in
                                                                     clti_list)), 'cpri_links_to_iphy must be 1 to 4')

        if enb_cpri_links is None:
            enb_cpri_links = [1, 13]
        if not isinstance(enb_cpri_links, list):
            raise Exception('enb_cpri_links must be Int list')
        self._set_attr("enb_cpri_links", enb_cpri_links, enb_cpri_links_validator)

        if not iphy_type:
            iphy_type = len(iphy_pdu_ip) * ['iphy']
        if not isinstance(iphy_type, list):
            raise Exception('iphy_type Must Be Str list')
        self._set_attr('iphy_type', iphy_type, iphy_type_validator)

        if not cpri_links_type:
            cpri_links_type = len(enb_cpri_links) * [0]
        if not isinstance(cpri_links_type, list):
            raise Exception('cpri_links_type must be Int list')
        if len(cpri_links_type) != len(enb_cpri_links):
            raise Exception('Length of cpri_links_type must match enb_cpri_links')
        self._set_attr('cpri_links_type', cpri_links_type, cpri_links_type_validator)

        if not cpri_links_to_iphy:
            cpri_links_to_iphy = len(enb_cpri_links) * [1]
        if not isinstance(cpri_links_to_iphy, list):
            raise Exception('cpri_links_to_iphy must be Int list')
        if len(cpri_links_to_iphy) != len(enb_cpri_links):
            raise Exception('Length of cpri_links_to_iphy must math enb_cpri_links')
        self._set_attr('cpri_links_to_iphy', cpri_links_to_iphy, cpri_links_to_iphy_validator)

        if not iphy_physical_id_list:
            iphy_physical_id_list = list(range(1, len(enb_cpri_links) + 1))
        if not isinstance(iphy_physical_id_list, list):
            raise Exception('iphy_physical_id_list must be Int list')
        if len(iphy_physical_id_list) != len(enb_cpri_links):
            raise Exception('Length of iphy_physical_id_list must math enb_cpri_links')
        self._set_attr('iphy_physical_id_list', iphy_physical_id_list)

        fdd_cpri_links_idx_list = [link_idx for link_idx in range(len(cpri_links_type)) if (cpri_links_type[link_idx] == 0 or
                                                                                            cpri_links_type[link_idx] == '0')]
        tdd_cpri_links_idx_list = [link_idx for link_idx in range(len(cpri_links_type)) if (int(cpri_links_type[link_idx]) in self.TDD_CPRI_TYPE)]
        fdd_cpri_links_list = [link_id for link_id in enb_cpri_links if enb_cpri_links.index(link_id) in fdd_cpri_links_idx_list]
        tdd_cpri_links_list = [link_id for link_id in enb_cpri_links if enb_cpri_links.index(link_id) in tdd_cpri_links_idx_list]
        self._set_attr("fdd_cpri_links_idx_list", fdd_cpri_links_idx_list)
        self._set_attr("tdd_cpri_links_idx_list", tdd_cpri_links_idx_list)
        self._set_attr("fdd_cpri_links_list", fdd_cpri_links_list)
        self._set_attr("tdd_cpri_links_list", tdd_cpri_links_list)

    def list_validator(self, config_items, item_type, validator, config_items_name):
        """
        used to verify the list para and change to list if not list
        """
        if isinstance(config_items, item_type):
            config_items = [config_items]

        if isinstance(config_items, list):
            for item in config_items:
                if not validator.validate(item).result:
                    error_msg = '{} check for {} failed, ' \
                                'please check the config file of your testline'.format(validator.__class__.__name__,
                                                                                       config_items_name)
                    raise Exception(error_msg)
        else:
            raise Exception('{} type should be {} or list of {} !'.format(config_items_name,
                                                                          item_type.__name__,
                                                                          item_type.__name__))

        return config_items

    def _classify_radios(self, radio_list):
        enb_cpri_to_re = {}
        if radio_list is None:
            self._set_attr("enb_cpri_to_re", enb_cpri_to_re)
            return
        for idx, radio_type in enumerate(radio_list):
            if radio_type in list(enb_cpri_to_re.keys()):
                enb_cpri_to_re[radio_type].append(self.enb_cpri_links[idx])
            else:
                enb_cpri_to_re[radio_type] = [self.enb_cpri_links[idx]]
        self._set_attr("enb_cpri_to_re", enb_cpri_to_re)
